const OrderSuccessPage: React.FC<OrderSuccessPageProps> = ({ order, storeInfo, onNavigateBack }) => {
  const [isDetailsOpen, setIsDetailsOpen] = useState(false);

  if (!order || !storeInfo) {
    return (
      <div className="min-h-screen flex flex-col items-center justify-center bg-gray-50 p-4 text-center">
        <p className="text-gray-500 mb-6">Não foi possível carregar o pedido.</p>
        <button
          onClick={onNavigateBack}
          className="px-6 py-2 bg-brand-primary text-white font-bold rounded-lg"
        >
          Voltar
        </button>
      </div>
    );
  }

  // Determine active step
  // 1: New/Pending (Pedido pendente)
  // 2: Confirmed (Preparo)
  // 3: Shipped (Envio/Saiu para entrega)
  // 4: Completed (Finalizado/Entregue)
  const getStepStatus = () => {
    if (order.status === 'completed' || order.status === 'archived') return 4;
    if (order.status === 'shipped') return 3;
    if (order.status === 'confirmed') return 2;
    return 1; // 'new' or 'pending_payment'
  };

  const activeStep = getStepStatus();

  // Header Banner Content
  const getBannerContent = () => {
      if (activeStep === 1) {
          return {
              title: "Pedido enviado!",
              subtitle: "Aguardando confirmação",
              icon: <ClockIcon className="w-8 h-8 animate-pulse" />,
              colorClass: "bg-gray-800 text-white"
          };
      }
      if (activeStep === 2) {
           return {
              title: "Em preparo!",
              subtitle: "Estamos caprichando",
              icon: <ChefHatIcon className="w-8 h-8" />,
              colorClass: "bg-green-500 text-white"
          };
      }
      if (activeStep === 3) {
           return {
              title: "Saiu para entrega!",
              subtitle: "Logo chega aí",
              icon: <BikeIcon className="w-8 h-8" />,
              colorClass: "bg-green-600 text-white"
          };
      }
      // activeStep 4 (Completed)
      return {
          title: "Pedido Entregue!",
          subtitle: "Obrigado!",
          icon: <CheckCircleIcon className="w-8 h-8" />,
          colorClass: "bg-green-700 text-white"
      };
  };

  const banner = getBannerContent();
  const totalPrice = (order.total || 0) + (order.deliveryFee || 0);

  const whatsappMessage = `Olá! Gostaria de falar sobre o pedido #${order.orderNumber}.`;
  const whatsappUrl = `https://wa.me/${storeInfo.whatsappNumber}?text=${encodeURIComponent(whatsappMessage)}`;

  return (
    <div className="min-h-screen bg-gray-50 flex flex-col">
      {/* Header */}
      <header className="bg-white shadow-sm sticky top-0 z-10">
        <div className="container mx-auto px-4 h-16 flex items-center">
          <button onClick={onNavigateBack} className="p-2 -ml-2 rounded-full hover:bg-gray-100 transition-colors">
            <ArrowLeftIcon className="w-6 h-6 text-gray-700" />
          </button>
          <h1 className="text-lg font-bold text-gray-800 ml-2">Acompanhamento</h1>
        </div>
      </header>

      <main className="flex-grow container mx-auto px-4 py-4 max-w-lg pb-32">

        {/* Status Banner */}
        <div className="bg-white rounded-lg shadow-sm p-4 mb-6 flex items-center gap-4 border border-gray-100">
            <div className={`w-12 h-12 rounded-full flex items-center justify-center flex-shrink-0 ${banner.colorClass}`}>
                {banner.icon}
            </div>
            <div>
                <h2 className="font-bold text-lg text-gray-900">{banner.title}</h2>
                <p className="text-gray-500 text-sm">{banner.subtitle}</p>
            </div>
        </div>

        {/* Timeline */}
        <div className="pl-2">
            <TrackingStep 
                title={activeStep === 1 ? "Pendente..." : "Recebido"}
                isActive={activeStep === 1}
                isCompleted={activeStep > 1}
                isLast={false}
                icon={<ClockIcon className="w-5 h-5" />}
            />
            <TrackingStep 
                title="Preparo"
                isActive={activeStep === 2}
                isCompleted={activeStep > 2}
                isLast={false}
                icon={<ChefHatIcon className="w-5 h-5" />}
            />
            <TrackingStep 
                title="Envio"
                isActive={activeStep === 3}
                isCompleted={activeStep > 3} // Only completed when delivered
                isLast={true}
                icon={<BikeIcon className="w-5 h-5" />}
            />
        </div>

      </main>

      {/* Bottom Store Card - Optimized Layout */}
      <div className="bg-white border-t border-gray-200 p-4 sticky bottom-0 safe-area-bottom z-40 shadow-[0_-4px_6px_-1px_rgba(0,0,0,0.05)]">
        <div className="container mx-auto max-w-lg">
            <div className="flex items-center gap-3 mb-3">
                <img src={storeInfo.logoUrl} alt={storeInfo.name} className="w-10 h-10 rounded-full bg-gray-100 object-cover border border-gray-100" />
                <div className="flex-grow min-w-0">
                    <h3 className="font-bold text-gray-900 truncate">{storeInfo.name}</h3>
                    <p className="text-xs text-gray-500">#{order.orderNumber.toString().padStart(4, '0')}</p>
                </div>
                <div className="text-right flex-shrink-0">
                    <p className="text-xs text-gray-500">Total</p>
                    <p className="text-base font-bold text-brand-primary">{formatPrice(totalPrice)}</p>
                </div>
            </div>

            <div className="flex gap-3">
                <a 
                    href={whatsappUrl}
                    target="_blank"
                    rel="noopener noreferrer"
                    className="flex-1 flex items-center justify-center gap-2 py-2.5 px-4 bg-green-50 border border-green-200 rounded-lg text-sm font-bold text-green-700 hover:bg-green-100 transition-colors"
                >
                    <WhatsappIcon className="w-4 h-4" />
                    Contato
                </a>
                <button 
                    onClick={() => setIsDetailsOpen(true)}
                    className="flex-1 flex items-center justify-center gap-2 py-2.5 px-4 border border-gray-300 rounded-lg text-sm font-bold text-gray-700 hover:bg-gray-50 transition-colors"
                >
                    Ver detalhes
                </button>
            </div>
        </div>
      </div>

      <OrderDetailsModal 
        order={order} 
        isOpen={isDetailsOpen} 
        onClose={() => setIsDetailsOpen(false)} 
      />
    </div>
  );
};

const formatPrice = (price: number) => {
    return price.toLocaleString('pt-BR', { style: 'currency', currency: 'BRL' });
};

export default OrderSuccessPage;

import React, { useState, useEffect } from 'react';
import type { Order } from '../types';
import { XIcon, ArrowLeftIcon } from './IconComponents';

interface OrderDetailModalProps {
    order: Order;
    isOpen: boolean;
    onClose: () => void;
    onStatusUpdate: (orderId: string, status: Order['status']) => Promise<void>;
    onCheckoutAction: (order: Order, deliveryFee: number, paymentLink: string) => Promise<void>;
    onPaymentLinkUpdate: (orderId: string, paymentLink: string) => Promise<void>;
}

const OrderDetailModal: React.FC<OrderDetailModalProps> = ({ order, isOpen, onClose, onStatusUpdate, onCheckoutAction, onPaymentLinkUpdate }) => {
    const [deliveryFee, setDeliveryFee] = useState<string>('');
    const [paymentLink, setPaymentLink] = useState<string>('');
    const [isSubmitting, setIsSubmitting] = useState(false);

    useEffect(() => {
        if (order) {
            setDeliveryFee(order.deliveryFee?.toString() || '');
            setPaymentLink(order.paymentLink || '');
        }
    }, [order]);

    useEffect(() => {
        if (isOpen) {
            document.body.style.overflow = 'hidden';
        } else {
            document.body.style.overflow = '';
        }
        return () => {
            document.body.style.overflow = '';
        };
    }, [isOpen]);

    if (!isOpen || !order) return null;

    const formatPrice = (price: number) => (price || 0).toLocaleString('pt-BR', { style: 'currency', currency: 'BRL' });
    const formatDisplayDate = (dateString: string) => {
        if (!dateString) return '';
        const date = new Date(dateString + 'T00:00:00');
        return new Intl.DateTimeFormat('pt-BR', { day: '2-digit', month: 'long', year: 'numeric' }).format(date);
    };

    const handleLinkBlur = async () => {
        if (paymentLink.trim() !== (order.paymentLink || '')) {
            await onPaymentLinkUpdate(order.id, paymentLink.trim());
        }
    };

    const handleActionClick = async (action: () => Promise<void>) => {
        setIsSubmitting(true);
        try {
            await action();
            onClose();
        } catch (e) {
            console.error(e);
            alert("Erro ao realizar ação.");
        } finally {
            setIsSubmitting(false);
        }
    };

    const handleCheckoutClick = async () => {
        const fee = parseFloat(deliveryFee);
        if (isNaN(fee)) {
            alert("Por favor, insira uma taxa de entrega válida.");
            return;
        }
        await handleActionClick(() => onCheckoutAction(order, fee, paymentLink));
    };

    const totalWithFee = (order.total || 0) + parseFloat(deliveryFee || '0');

    const ActionBtn: React.FC<{ onClick: () => void, colorClass: string, children: React.ReactNode }> = ({ onClick, colorClass, children }) => (
        <button 
            onClick={onClick} 
            disabled={isSubmitting} 
            className={`w-full sm:w-auto px-4 py-2 text-sm font-bold rounded-lg shadow-sm transition-all active:scale-95 disabled:opacity-50 disabled:active:scale-100 ${colorClass}`}
        >
            {children}
        </button>
    );

    const actionButtons = () => {
        switch (order.status) {
            case 'new':
                return (
                    <>
                        <ActionBtn onClick={handleCheckoutClick} colorClass="text-white bg-green-600 hover:bg-green-700">
                            Checkout
                        </ActionBtn>
                        <ActionBtn onClick={() => { handleActionClick(() => onStatusUpdate(order.id, 'archived')); }} colorClass="text-gray-700 bg-gray-100 hover:bg-gray-200">
                            Arquivar
                        </ActionBtn>
                    </>
                );
            case 'pending_payment':
                return (
                    <>
                        <ActionBtn onClick={() => { handleActionClick(() => onStatusUpdate(order.id, 'confirmed')); }} colorClass="text-white bg-blue-600 hover:bg-blue-700">
                            Confirmar Pagamento
                        </ActionBtn>
                        <ActionBtn onClick={() => { handleActionClick(() => onStatusUpdate(order.id, 'archived')); }} colorClass="text-gray-700 bg-gray-100 hover:bg-gray-200">
                            Arquivar
                        </ActionBtn>
                    </>
                );
            case 'confirmed':
                return (
                    <>
                        <ActionBtn onClick={() => { handleActionClick(() => onStatusUpdate(order.id, 'shipped')); }} colorClass="text-white bg-indigo-600 hover:bg-indigo-700">
                            Enviar Entrega
                        </ActionBtn>
                        <ActionBtn onClick={() => { handleActionClick(() => onStatusUpdate(order.id, 'archived')); }} colorClass="text-gray-700 bg-gray-100 hover:bg-gray-200">
                            Arquivar
                        </ActionBtn>
                    </>
                );
            case 'shipped':
                return (
                    <>
                        <ActionBtn onClick={() => { handleActionClick(() => onStatusUpdate(order.id, 'completed')); }} colorClass="text-white bg-green-600 hover:bg-green-700">
                            Finalizar Pedido
                        </ActionBtn>
                        <ActionBtn onClick={() => { handleActionClick(() => onStatusUpdate(order.id, 'archived')); }} colorClass="text-gray-700 bg-gray-100 hover:bg-gray-200">
                            Arquivar
                        </ActionBtn>
                    </>
                );
            case 'completed':
                return (
                    <ActionBtn onClick={() => { handleActionClick(() => onStatusUpdate(order.id, 'archived')); }} colorClass="text-gray-700 bg-gray-100 hover:bg-gray-200">
                        Arquivar
                    </ActionBtn>
                );
            default:
                return null;
        }
    };

    return (
        <div className="fixed inset-0 z-[60] flex items-center justify-center p-4">
            <div 
                className="absolute inset-0 bg-black/60 backdrop-blur-sm"
                onClick={onClose}
                aria-hidden="true"
            />

            <div className="relative bg-white rounded-lg shadow-xl w-full max-w-lg max-h-[90vh] flex flex-col overflow-hidden">
                <div className="flex-1 overflow-y-auto px-6 pt-6 pb-12 space-y-6">
                    <header className="flex items-center justify-between border-b pb-4">
                        <div>
                            <p className="text-xs font-bold text-brand-primary uppercase tracking-wide">Pedido #{order.orderNumber}</p>
                            <h3 className="text-lg font-bold text-brand-text truncate max-w-[250px]">{order.customer?.name}</h3>
                        </div>
                        <button onClick={onClose} className="p-2 rounded-full hover:bg-gray-100">
                            <XIcon className="w-5 h-5 text-gray-600" />
                        </button>
                    </header>

                    <div className="space-y-4">
                        <div className="bg-gray-50 p-3 rounded-lg border border-gray-100">
                            <h4 className="font-bold text-sm text-gray-700 mb-2">Itens do Pedido</h4>
                            <ul className="space-y-3">
                                {order.items?.map((item, index) => (
                                    <li key={index} className="flex gap-3">
                                        {item.imageUrl ? (
                                            <img src={item.imageUrl} alt={item.name} className="w-12 h-12 object-cover rounded-md flex-shrink-0 bg-white border border-gray-200" />
                                        ) : (
                                            <div className="w-12 h-12 bg-white rounded-md border border-gray-200 flex items-center justify-center flex-shrink-0">
                                                <div className="w-4 h-4 bg-gray-100 rounded-full"></div>
                                            </div>
                                        )}
                                        <div className="flex-grow min-w-0">
                                            <div className="flex justify-between items-start gap-2">
                                                <span className="text-sm">
                                                    <span className="font-bold text-gray-800">{item.quantity}x</span> {item.name}
                                                </span>
                                                <span className="font-bold text-sm text-gray-900 whitespace-nowrap">
                                                    {formatPrice(item.price * item.quantity)}
                                                </span>
                                            </div>
                                            {item.option && <span className="text-gray-500 text-[10px] uppercase font-bold block">{item.option}</span>}
                                            {item.observations && <span className="text-amber-600 text-[10px] block italic bg-amber-50 px-1 rounded mt-0.5">Obs: {item.observations}</span>}
                                        </div>
                                    </li>
                                ))}
                            </ul>
                        </div>

                        <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                            <div>
                                <h4 className="font-bold text-xs text-gray-400 uppercase mb-1">Cliente</h4>
                                <p className="text-sm font-medium text-gray-800">{order.customer?.name}</p>
                                <a href={`tel:${order.customer?.whatsapp}`} className="text-sm text-brand-primary hover:underline">{order.customer?.whatsapp}</a>
                            </div>
                            <div>
                                <h4 className="font-bold text-xs text-gray-400 uppercase mb-1">Pagamento</h4>
                                <p className="text-sm font-medium text-gray-800">{order.paymentMethod}</p>
                            </div>
                            <div className="sm:col-span-2">
                                <h4 className="font-bold text-xs text-gray-400 uppercase mb-1">Entrega</h4>
                                <p className="text-sm text-gray-800 leading-snug bg-blue-50 p-2 rounded border border-blue-100">
                                    {order.delivery?.address ? `${order.delivery.address.street}, ${order.delivery.address.number}` : 'Endereço não informado'}
                                    <br/>
                                    {order.delivery?.address?.neighborhood}
                                    {order.delivery?.address?.complement && ` - ${order.delivery.address.complement}`}
                                </p>
                                <p className="text-xs text-gray-500 mt-1">Agendado para: <span className="font-semibold text-gray-700">{formatDisplayDate(order.deliveryDate)}</span></p>
                            </div>
                        </div>

                        <div className="border-t pt-4 space-y-4">
                            <div className="flex flex-col sm:flex-row sm:items-center gap-2">
                                <label htmlFor={`deliveryFee-${order.id}`} className="text-sm font-bold text-gray-700 min-w-[120px]">Taxa de Entrega:</label>
                                <div className="relative flex-grow">
                                    <span className="absolute left-3 top-1/2 -translate-y-1/2 text-gray-500 text-sm">R$</span>
                                    <input
                                        id={`deliveryFee-${order.id}`}
                                        type="number"
                                        step="0.01"
                                        value={deliveryFee}
                                        onChange={(e) => setDeliveryFee(e.target.value)}
                                        className="w-full pl-8 pr-3 py-2 bg-white border border-gray-300 rounded-lg shadow-sm focus:ring-2 focus:ring-brand-primary focus:border-brand-primary text-sm font-medium"
                                        placeholder="0,00"
                                    />
                                </div>
                            </div>

                            <div className="flex flex-col gap-1">
                                <label htmlFor={`paymentLink-${order.id}`} className="text-sm font-bold text-gray-700">Link de Pagamento:</label>
                                <input
                                    id={`paymentLink-${order.id}`}
                                    type="url"
                                    value={paymentLink}
                                    onChange={(e) => setPaymentLink(e.target.value)}
                                    onBlur={handleLinkBlur}
                                    className="w-full px-3 py-2 bg-white border border-gray-300 rounded-lg shadow-sm focus:ring-2 focus:ring-brand-primary focus:border-brand-primary text-sm text-gray-600"
                                    placeholder="Cole o link aqui"
                                />
                            </div>

                            <div className="bg-gray-50 p-3 rounded-lg space-y-1 mt-2">
                                <div className="flex justify-between text-sm text-gray-600">
                                    <span>Subtotal</span>
                                    <span>{formatPrice(order.total)}</span>
                                </div>
                                <div className="flex justify-between text-sm text-gray-600">
                                    <span>Frete</span>
                                    <span>{formatPrice(parseFloat(deliveryFee || '0'))}</span>
                                </div>
                                <div className="flex justify-between text-lg font-bold text-brand-text border-t border-gray-200 pt-2 mt-1">
                                    <span>Total</span>
                                    <span>{formatPrice(totalWithFee)}</span>
                                </div>
                            </div>
                        </div>
                    </div>

                    <div className="flex flex-col sm:flex-row gap-3 sm:justify-end pt-2">
                        {actionButtons()}
                    </div>
                </div>
            </div>
        </div>
    );
};

export default OrderDetailModal;

import React, { useState } from 'react';
import type { Order, StoreInfoData } from '../types';
import { ArrowLeftIcon, ClockIcon, WhatsappIcon, CheckCircleIcon, ChefHatIcon, BikeIcon, XIcon } from './IconComponents';

interface OrderSuccessPageProps {
  order: Order | null;
  storeInfo: StoreInfoData | null;
  onNavigateBack: () => void;
}

interface StepProps {
    isActive: boolean;
    isCompleted: boolean;
    isLast: boolean;
    icon: React.ReactNode;
    title: string;
}

const TrackingStep: React.FC<StepProps> = ({ isActive, isCompleted, isLast, icon, title }) => {

    let bubbleClass = 'bg-gray-100 text-gray-400';
    let textClass = 'text-gray-400';
    let lineClass = 'bg-gray-200';

    if (isActive) {
        bubbleClass = 'bg-green-100 text-green-600';
        textClass = 'text-gray-900';
    } else if (isCompleted) {
        bubbleClass = 'bg-green-100 text-green-600';
        textClass = 'text-gray-800';
        lineClass = 'bg-green-200';
    }

    return (
        <div className="flex gap-4 relative">
            <div className="flex flex-col items-center">
                <div className={`w-10 h-10 rounded-full flex items-center justify-center z-10 transition-colors duration-300 ${bubbleClass}`}>
                    {isCompleted && !isActive ? <CheckCircleIcon className="w-6 h-6" /> : icon}
                </div>
                {!isLast && (
                    <div className={`w-0.5 flex-grow my-1 transition-colors duration-300 ${lineClass}`} style={{ minHeight: '24px' }}></div>
                )}
            </div>
            <div className="pt-2 pb-5">
                <h3 className={`font-semibold text-lg transition-colors duration-300 ${textClass}`}>
                    {title}
                </h3>
            </div>
        </div>
    );
};

const OrderItemsList: React.FC<{ order: Order }> = ({ order }) => (
    <div className="space-y-4">
        {order.items.map((item, idx) => (
            <div key={idx} className="flex items-center gap-3">
                {item.imageUrl ? (
                    <img src={item.imageUrl} alt={item.name} className="w-14 h-14 object-cover rounded-lg flex-shrink-0 bg-gray-100 border border-gray-100" />
                ) : (
                    <div className="w-14 h-14 bg-gray-50 rounded-lg border border-gray-100 flex items-center justify-center flex-shrink-0">
                        <div className="w-5 h-5 bg-gray-200 rounded-full"></div>
                    </div>
                )}
                <div className="flex-grow min-w-0">
                    <div className="flex justify-between items-start gap-2">
                        <span className="text-gray-700 font-bold text-sm leading-tight">{item.quantity}x {item.name}</span>
                        <span className="font-bold text-sm whitespace-nowrap">{(item.price * item.quantity).toLocaleString('pt-BR', { style: 'currency', currency: 'BRL' })}</span>
                    </div>
                    {item.option && <p className="text-[10px] text-gray-400 uppercase font-black mt-0.5">{item.option}</p>}
                    {item.observations && <p className="text-[10px] text-amber-600 italic bg-amber-50 px-1 rounded inline-block mt-1">Obs: {item.observations}</p>}
                </div>
            </div>
        ))}
        <div className="pt-3 border-t border-dashed border-gray-200">
            {order.deliveryFee ? (
                    <div className="flex justify-between text-sm text-gray-500 mb-1">
                    <span>Taxa de entrega</span>
