            ) : null}
            <div className="flex justify-between font-black text-brand-text text-xl pt-1">
                <span>Total</span>
                <span>{(order.total + (order.deliveryFee || 0)).toLocaleString('pt-BR', { style: 'currency', currency: 'BRL' })}</span>
            </div>
        </div>
    </div>
);

