import React, { useState, useEffect } from 'react';
import { XIcon, ArrowLeftIcon, ChevronRightIcon } from './IconComponents';
import { getOrdersByWhatsapp } from '../services/menuService';
import type { Order } from '../types';

interface OrderTrackingModalProps {
  isOpen: boolean;
  onClose: () => void;
  onTrackOrder: (order: Order) => void;
  initialOrders?: Order[];
}

const OrderTrackingModal: React.FC<OrderTrackingModalProps> = ({ isOpen, onClose, onTrackOrder, initialOrders }) => {
  const [step, setStep] = useState<'input' | 'results'>('input');
  const [whatsapp, setWhatsapp] = useState('');
  const [orders, setOrders] = useState<Order[]>([]);
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState('');

  useEffect(() => {
    if (isOpen) {
        if (initialOrders && initialOrders.length > 0) {
            setOrders(initialOrders);
            setStep('results');
        } else {
            setStep('input');
            setOrders([]);
            setWhatsapp('');
        }
    }
  }, [isOpen]);

  const handleClose = () => {
    onClose();
    setTimeout(() => {
        setStep('input');
        setWhatsapp('');
        setOrders([]);
        setError('');
    }, 300);
  };

  const handleSearch = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!whatsapp.trim()) {
      setError('Por favor, digite seu número de WhatsApp.');
      return;
    }
    setIsLoading(true);
    setError('');
    try {
      const foundOrders = await getOrdersByWhatsapp(whatsapp);
      setOrders(foundOrders);
      setStep('results');
    } catch (err) {
      setError('Ocorreu um erro ao buscar seus pedidos. Tente novamente.');
    } finally {
      setIsLoading(false);
    }
  };

  const statusPill = (status: Order['status']) => {
    const styles = {
        new: 'bg-yellow-100 text-yellow-800',
        pending_payment: 'bg-orange-100 text-orange-800',
        confirmed: 'bg-blue-100 text-blue-800',
        shipped: 'bg-indigo-100 text-indigo-800',
        completed: 'bg-green-100 text-green-800',
        archived: 'bg-gray-100 text-gray-800',
    };
    const text = {
        new: 'Recebido',
        pending_payment: 'Pendente',
        confirmed: 'Preparo',
        shipped: 'Enviado',
        completed: 'Finalizado',
        archived: 'Arquivado'
    }
    return <span className={`px-2 py-0.5 text-[10px] font-black uppercase rounded-full ${styles[status] || styles.new}`}>{text[status] || text.new}</span>;
  };

  return (
    <>
      <div
        className={`fixed inset-0 bg-black/60 z-40 transition-opacity duration-300 flex items-center justify-center p-4 backdrop-blur-sm ${
          isOpen ? 'opacity-100' : 'opacity-0 pointer-events-none'
        }`}
        onClick={handleClose}
        aria-hidden="true"
      />
      <div
        className={`fixed inset-0 z-50 flex items-center justify-center p-4 transition-all duration-300 ease-in-out ${
          isOpen ? 'opacity-100 scale-100' : 'opacity-0 scale-95 pointer-events-none'
        }`}
        role="dialog"
        aria-modal="true"
      >
        <div className="relative bg-white rounded-2xl shadow-2xl max-w-md w-full max-h-[90vh] flex flex-col overflow-hidden">
          <header className="flex items-center justify-between p-4 border-b bg-gray-50">
            <div className="flex items-center">
                {step === 'results' && (
                    <button onClick={() => setStep('input')} className="p-2 -ml-2 mr-2 rounded-full hover:bg-gray-200">
                        <ArrowLeftIcon className="w-5 h-5 text-gray-600" />
                    </button>
                )}
                <h2 className="text-lg font-black text-brand-text uppercase tracking-tight">Meus Pedidos</h2>
            </div>
            <button onClick={handleClose} className="p-2 rounded-full hover:bg-gray-200 transition-colors">
              <XIcon className="w-5 h-5 text-gray-600" />
            </button>
          </header>

          <div className="overflow-y-auto p-6 no-scrollbar">
            {step === 'input' ? (
              <form onSubmit={handleSearch} className="space-y-6">
                <p className="text-sm text-gray-500 leading-relaxed">Para encontrar seus pedidos em andamento, digite o número de WhatsApp que você usou na compra.</p>
                <div>
                  <label htmlFor="whatsapp-tracker" className="block text-xs font-black text-gray-400 uppercase tracking-widest mb-1">
                    Seu WhatsApp
                  </label>
                  <input
                    type="tel"
                    id="whatsapp-tracker"
                    value={whatsapp}
                    onChange={(e) => setWhatsapp(e.target.value)}
                    className="block w-full px-4 py-3 bg-gray-50 border border-gray-200 rounded-xl text-gray-900 placeholder-gray-400 focus:outline-none focus:ring-2 focus:ring-brand-primary focus:bg-white transition-all shadow-inner"
                    placeholder="(11) 91234-5678"
                    required
                  />
                </div>
                {error && <p className="text-xs font-bold text-red-600 bg-red-50 p-2 rounded-lg">{error}</p>}
                <button
                  type="submit"
                  disabled={isLoading}
                  className="w-full flex justify-center py-4 px-4 bg-brand-primary text-white rounded-xl text-sm font-black shadow-lg hover:bg-brand-primary-dark transition-all active:scale-95 disabled:opacity-50"
                >
                  {isLoading ? 'BUSCANDO...' : 'BUSCAR MEUS PEDIDOS'}
                </button>
              </form>
            ) : (
                <div className="space-y-4">
                    {orders.length > 0 ? (
                        orders.map(order => (
                            <button 
                              key={order.id} 
                              onClick={() => onTrackOrder(order)}
                              className="w-full text-left bg-white hover:bg-gray-50 p-4 rounded-xl border border-gray-100 shadow-sm transition-all flex items-center gap-4 group active:scale-[0.98]"
                            >
                                <div className="flex-shrink-0 w-16 h-16 rounded-lg bg-gray-100 overflow-hidden relative">
                                    {order.items[0]?.imageUrl ? (
                                        <img src={order.items[0].imageUrl} className="w-full h-full object-cover" alt="item"/>
                                    ) : (
                                        <div className="w-full h-full flex items-center justify-center text-gray-300"><div className="w-4 h-4 bg-current rounded-full"></div></div>
                                    )}
                                    {order.items.length > 1 && (
                                        <div className="absolute bottom-0 right-0 bg-black/60 text-white text-[8px] font-black px-1.5 py-0.5 rounded-tl-md">
                                            +{order.items.length - 1}
                                        </div>
                                    )}
                                </div>
                                <div className="flex-grow min-w-0">
                                    <div className="flex justify-between items-start mb-1">
                                        <p className="font-black text-brand-primary text-sm uppercase">Pedido #{order.orderNumber}</p>
                                        {statusPill(order.status)}
                                    </div>
                                    <p className="text-[10px] font-bold text-gray-400 uppercase truncate">
                                        {order.items.map(i => i.name).join(', ')}
                                    </p>
                                    <p className="text-[10px] text-gray-400 mt-1">
                                        Entrega: {new Date(order.deliveryDate + 'T00:00:00').toLocaleDateString('pt-BR')}
                                    </p>
                                </div>
                                <ChevronRightIcon className="w-5 h-5 text-gray-300 group-hover:text-brand-primary transition-colors" />
                            </button>
                        ))
                    ) : (
                        <div className="text-center py-12">
                            <div className="w-16 h-16 bg-gray-50 rounded-full flex items-center justify-center mx-auto mb-4">
                                <XIcon className="w-8 h-8 text-gray-300" />
                            </div>
                            <p className="font-black text-brand-text uppercase tracking-tight">Nenhum pedido encontrado</p>
                            <p className="text-sm text-gray-500 mt-2">Verifique o número e tente novamente.</p>
                        </div>
                    )}
                </div>
            )}
          </div>
        </div>
      </div>
    </>
  );
};

export default OrderTrackingModal;

import React, { useState, useEffect, useCallback, useMemo } from 'react';
import StoreInfo from './components/StoreInfo';
import CategoryTabs from './components/CategoryTabs';
import ProductCard from './components/ProductCard';
import Footer from './components/Footer';
import LoginPage from './components/LoginPage';
import AdminPage from './components/AdminPage';
import StoreInfoModal from './components/StoreInfoModal';
import CategoryMenuModal from './components/CategoryMenuModal';
import ProductDetailModal from './components/ProductDetailModal';
import CartButton from './components/CartButton';
import CheckoutPage from './components/CheckoutPage';
import OrderSuccessPage from './components/OrderSuccessPage';
import OrderTrackingModal from './components/OrderTrackingModal';
import { BikeIcon, ShoppingBagIcon, ChevronRightIcon } from './components/IconComponents';
import type { Product, CartItem, StoreInfoData, Order, ProductOption, CategoryMetadata } from './types';
import { getMenu, addProduct, getStoreInfo, updateStoreInfo, updateProduct, deleteProduct, addCategory, deleteCategory, initializeFirebaseData, updateCategoryOrder, incrementVisitCount, getOrderById, toggleCategoriesArchive } from './services/menuService';
import { auth } from './firebase';
import { onAuthStateChanged, signOut } from 'firebase/auth';

const App: React.FC = () => {
  const [products, setProducts] = useState<Product[]>([]);
  const [categories, setCategories] = useState<CategoryMetadata[]>([]);
  const [storeInfo, setStoreInfo] = useState<StoreInfoData | null>(null);
  const [selectedCategory, setSelectedCategory] = useState<string>('Todos');
  const [isLoading, setIsLoading] = useState<boolean>(true);
  const [view, setView] = useState<'menu' | 'login' | 'admin' | 'checkout' | 'orderSuccess'>('menu');
  const [orderSuccessData, setOrderSuccessData] = useState<Order | null>(null);
  const [isAuthenticated, setIsAuthenticated] = useState<boolean>(false);
  const [isStoreInfoModalOpen, setStoreInfoModalOpen] = useState(false);
  const [isCategoryMenuOpen, setCategoryMenuOpen] = useState(false);
  const [searchQuery, setSearchQuery] = useState('');
  const [selectedProduct, setSelectedProduct] = useState<Product | null>(null);
  const [cartItems, setCartItems] = useState<CartItem[]>([]);
  const [isOrderTrackingOpen, setIsOrderTrackingOpen] = useState(false);

  const [activeOrders, setActiveOrders] = useState<Order[]>([]);

  useEffect(() => {
    incrementVisitCount();
    const unsubscribe = onAuthStateChanged(auth, (user) => {
      if (user) {
        setIsAuthenticated(true);
      } else {
        setIsAuthenticated(false);
        setView(currentView => currentView === 'admin' ? 'login' : currentView);
      }
    });
    return () => unsubscribe();
  }, []);

  useEffect(() => {
    const checkActiveOrders = async () => {
      let ids: string[] = [];
      const legacyId = localStorage.getItem('activeOrderId');
      if (legacyId) ids.push(legacyId);
      const storedIds = localStorage.getItem('activeOrderIds');
      if (storedIds) {
        try {
          const parsed = JSON.parse(storedIds);
          if (Array.isArray(parsed)) {
            ids = [...ids, ...parsed];
          }
        } catch (e) {
          console.error("Error parsing activeOrderIds", e);
        }
      }
      ids = [...new Set(ids)];
      if (ids.length === 0) {
        setActiveOrders([]);
        return;
      }
      const promises = ids.map(id => getOrderById(id));
      const results = await Promise.all(promises);
      const validOrders: Order[] = [];
      const validIds: string[] = [];
      results.forEach(order => {
        if (order && order.status !== 'archived' && order.status !== 'completed') {
            validOrders.push(order);
            validIds.push(order.id);
        }
      });
      validOrders.sort((a, b) => b.orderNumber - a.orderNumber);
      setActiveOrders(validOrders);
      if (validIds.length !== ids.length || legacyId) {
          localStorage.setItem('activeOrderIds', JSON.stringify(validIds));
          localStorage.removeItem('activeOrderId');
      }
    };
    checkActiveOrders();
    const interval = setInterval(checkActiveOrders, 30000);
    return () => clearInterval(interval);
  }, []);

  useEffect(() => {
    const isModalOpen = isStoreInfoModalOpen || isCategoryMenuOpen || !!selectedProduct || isOrderTrackingOpen;
    if (isModalOpen) {
      document.body.style.overflow = 'hidden';
    } else {
      document.body.style.overflow = 'auto';
    }
    return () => {
      document.body.style.overflow = 'auto';
    };
  }, [isStoreInfoModalOpen, isCategoryMenuOpen, selectedProduct, isOrderTrackingOpen]);

  const fetchInitialData = useCallback(async () => {
    setIsLoading(true);
    try {
        await initializeFirebaseData();
        const [menuResult, storeInfoResult] = await Promise.all([getMenu(), getStoreInfo()]);
        setProducts(menuResult.products);
        setCategories(menuResult.categories);
        setStoreInfo(storeInfoResult);
    } catch (error) {
        console.error("Failed to fetch initial data", error);
    } finally {
        setIsLoading(false);
    }
  }, []);

  useEffect(() => {
    if (view === 'menu' || (view === 'admin' && isAuthenticated)) {
        fetchInitialData();
    }
  }, [view, isAuthenticated, fetchInitialData]);

  const handleSelectCategory = useCallback((category: string) => {
    setSelectedCategory(category);
  }, []);

  const handleModalCategorySelect = useCallback((category: string) => {
    setSelectedCategory(category);
    setCategoryMenuOpen(false);
  }, []);

  const handleAddProduct = useCallback(async (productData: Omit<Product, 'id'>) => {
    await addProduct(productData);
    await fetchInitialData(); 
  }, [fetchInitialData]);

  const handleUpdateProduct = useCallback(async (productData: Product) => {
      await updateProduct(productData);
      await fetchInitialData();
  }, [fetchInitialData]);

   const handleDeleteProduct = useCallback(async (productId: string) => {
      try {
        await deleteProduct(productId);
        setProducts(prevProducts => prevProducts.filter(p => p.id !== productId));
      } catch (error) {
        console.error("Failed to delete product. Refetching to sync.", error);
        await fetchInitialData();
      }
  }, [fetchInitialData]);

  const handleUpdateStoreInfo = useCallback(async (storeInfoData: StoreInfoData) => {
      await updateStoreInfo(storeInfoData);
      await fetchInitialData();
  }, [fetchInitialData]);

  const handleAddCategory = useCallback(async (categoryName: string) => {
    const updatedCategories = await addCategory(categoryName);
    setCategories(updatedCategories);
  }, []);

  const handleDeleteCategory = useCallback(async (categoryName: string) => {
      const updatedCategories = await deleteCategory(categoryName);
      setCategories(updatedCategories);
      if (selectedCategory === categoryName) {
        setSelectedCategory('Todos');
      }
  }, [selectedCategory]);

  const handleUpdateCategoryOrder = useCallback(async (newOrder: CategoryMetadata[]) => {
      try {
          await updateCategoryOrder(newOrder);
          setCategories(newOrder);
      } catch (error) {
          console.error("Failed to update category order", error);
          await fetchInitialData();
      }
  }, [fetchInitialData]);

  const handleToggleCategoriesArchive = useCallback(async (categoryNames: string[], archive: boolean) => {
      try {
          const updated = await toggleCategoriesArchive(categoryNames, archive);
          setCategories(updated);
          if (archive && categoryNames.includes(selectedCategory)) {
              setSelectedCategory('Todos');
          }
      } catch (error) {
          console.error("Failed to archive categories", error);
      }
  }, [selectedCategory]);

  const handleProductClick = useCallback((product: Product) => {
    setSelectedProduct(product);
  }, []);

  const handleCloseModal = useCallback(() => {
    setSelectedProduct(null);
  }, []);

  const handleAddToCart = useCallback((productToAdd: Product, quantity: number, observations?: string, selectedOption?: ProductOption) => {
    setCartItems(prevItems => {
        const existingItemIndex = prevItems.findIndex(item => 
            item.id === productToAdd.id && 
            item.selectedOption?.name === selectedOption?.name
        );
        if (existingItemIndex !== -1) {
            const newItems = [...prevItems];
            newItems[existingItemIndex] = {
                ...newItems[existingItemIndex],
                quantity: newItems[existingItemIndex].quantity + quantity,
                observations: observations 
            };
            return newItems;
        } else {
            const itemPrice = selectedOption ? selectedOption.price : productToAdd.price;
            return [...prevItems, { 
                ...productToAdd, 
                price: itemPrice,
                quantity, 
                observations, 
                selectedOption 
            }];
        }
    });
    setSelectedProduct(null);
  }, []);

  const handleUpdateCartQuantity = useCallback((productId: string, newQuantity: number, optionName?: string) => {
    setCartItems(prev => {
        if (newQuantity <= 0) {
            return prev.filter(item => !(item.id === productId && item.selectedOption?.name === optionName));
        }
        return prev.map(item =>
            (item.id === productId && item.selectedOption?.name === optionName) 
                ? { ...item, quantity: newQuantity } 
                : item
        );
    });
  }, []);

  const handleRemoveFromCart = useCallback((productId: string, optionName?: string) => {
    setCartItems(prev => prev.filter(item => !(item.id === productId && item.selectedOption?.name === optionName)));
  }, []);

  const handleGoToCheckout = useCallback(() => {
    setView('checkout');
  }, []);

  const handleOrderSuccess = (order: Order) => {
    setOrderSuccessData(order);
    setCartItems([]);
    setActiveOrders(prev => {
        const exists = prev.some(o => o.id === order.id);
        const newOrders = exists 
            ? prev.map(o => o.id === order.id ? order : o) 
            : [order, ...prev];
        const ids = newOrders.map(o => o.id);
        localStorage.setItem('activeOrderIds', JSON.stringify(ids));
        localStorage.removeItem('activeOrderId');
        return newOrders;
    });
    setView('orderSuccess');
  };

  const handleTrackOrder = useCallback((order: Order) => {
    setOrderSuccessData(order);
    setView('orderSuccess');
    setIsOrderTrackingOpen(false);
  }, []);

  const handleBannerClick = () => {
    if (activeOrders.length === 1) {
        setOrderSuccessData(activeOrders[0]);
        setView('orderSuccess');
    } else if (activeOrders.length > 1) {
        setIsOrderTrackingOpen(true);
    }
  };

  const handleLogout = async () => {
    try {
      await signOut(auth);
      setView('login');
    } catch (error) {
      console.error("Error signing out", error);
    }
  };

  const SectionTitle: React.FC<{ title: string }> = ({ title }) => (
    <div className="flex justify-between items-center mb-6 mt-10">
        <div className="flex items-center space-x-3">
            <div className="w-1.5 h-6 bg-brand-primary rounded-full"></div>
            <h2 className="text-xl font-bold text-brand-text tracking-tight">{title}</h2>
        </div>
    </div>
  );

  const activeCategoriesList = useMemo(() => {
      return categories.filter(c => !c.isArchived).map(c => c.name);
  }, [categories]);

  const allVisibleCategoriesForTabs = useMemo(() => {
    const productCategories = new Set(products.map(p => p.category));
    const activeOfficial = activeCategoriesList;
    const orphanCategories = Array.from(productCategories).filter(cat => 
        cat && cat !== 'Todos' && !activeOfficial.includes(cat) && 
        !categories.some(c => c.name === cat && c.isArchived)
    );
    return [...activeOfficial, ...orphanCategories];
  }, [activeCategoriesList, products, categories]);

  const renderMenu = () => {
    const categoriesWithProducts = allVisibleCategoriesForTabs.filter(category => 
        products.some(p => p.category === category)
    );
    const visibleCategoriesForTabs = ['Todos', ...categoriesWithProducts];

    const getStatusText = (status: Order['status']) => {
        const texts = {
            new: 'Recebido',
            pending_payment: 'Pagamento Pendente',
            confirmed: 'Em Preparo',
            shipped: 'Saiu para entrega',
            completed: 'Finalizado',
            archived: ''
        };
        return texts[status] || 'Em andamento';
    };

    return (
        <>
        <div className="min-h-screen flex flex-col bg-gray-50">
            {activeOrders.length > 0 && (
                <div 
                    onClick={handleBannerClick}
                    className="bg-brand-primary text-white py-3 px-4 cursor-pointer shadow-lg flex items-center justify-between animate-fade-in"
                >
                    {activeOrders.length === 1 ? (
                        <>
                            <div className="flex items-center gap-3 min-w-0">
                                <div className="w-10 h-10 rounded-lg overflow-hidden bg-white/10 flex-shrink-0">
                                    {activeOrders[0].items[0]?.imageUrl ? (
                                        <img src={activeOrders[0].items[0].imageUrl} className="w-full h-full object-cover" alt="pedido"/>
                                    ) : (
                                        <div className="w-full h-full flex items-center justify-center"><BikeIcon className="w-5 h-5 text-white" /></div>
                                    )}
                                </div>
                                <div className="min-w-0">
                                    <p className="text-[10px] font-black uppercase text-brand-secondary opacity-70 leading-none mb-1">Pedido em andamento</p>
                                    <p className="text-sm font-bold truncate leading-none">
                                        #{activeOrders[0].orderNumber} • {getStatusText(activeOrders[0].status)}
                                    </p>
                                </div>
                            </div>
                            <div className="bg-white/10 px-3 py-1.5 rounded-lg text-[10px] font-black uppercase hover:bg-white/20 transition-colors flex items-center gap-1 flex-shrink-0">
                                Acompanhar <ChevronRightIcon className="w-3 h-3" />
                            </div>
                        </>
                    ) : (
                        <>
                            <div className="flex items-center gap-3">
                                <div className="bg-white/20 p-2 rounded-xl">
                                    <ShoppingBagIcon className="w-5 h-5 text-white" />
                                </div>
                                <div>
                                    <p className="text-[10px] font-black uppercase text-brand-secondary opacity-70 leading-none mb-1">Pedidos Ativos</p>
                                    <p className="text-sm font-bold leading-none">
                                        Você tem {activeOrders.length} pedidos em andamento
                                    </p>
                                </div>
                            </div>
                            <div className="bg-white/10 px-3 py-1.5 rounded-lg text-[10px] font-black uppercase hover:bg-white/20 transition-colors flex items-center gap-1 flex-shrink-0">
                                Ver Todos <ChevronRightIcon className="w-3 h-3" />
                            </div>
                        </>
                    )}
                </div>
            )}
            <main className="flex-grow">
            <StoreInfo 
                storeInfo={storeInfo} 
                isLoading={!storeInfo}
                onOpenModal={() => setStoreInfoModalOpen(true)}
                onOpenOrderTracker={() => setIsOrderTrackingOpen(true)}
            />
            <CategoryTabs
                categories={categoriesWithProducts}
                selectedCategory={selectedCategory}
                onSelectCategory={handleSelectCategory}
                onOpenMenu={() => setCategoryMenuOpen(true)}
                onSearch={setSearchQuery}
                searchQuery={searchQuery}
            />
            <div className="container mx-auto px-4 sm:px-6 lg:px-8 py-4">
                {isLoading ? (
                <div>
                    {Array.from({length: 2}).map((_, i) => (
                        <div key={i}>
                            <div className="h-6 bg-gray-200 rounded w-1/3 animate-pulse mb-4 mt-8"></div>
                            <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-4">
                                {Array.from({length: 3}).map((_, index) => (
                                    <div key={index} className="flex items-center bg-white p-2 rounded-lg gap-4 animate-pulse">
                                        <div className="w-24 h-24 sm:w-32 sm:h-32 bg-gray-200 rounded-md"></div>
                                        <div className="flex-grow space-y-3 py-2">
                                            <div className="h-5 bg-gray-200 rounded w-3/4"></div>
                                            <div className="h-4 bg-gray-200 rounded w-full hidden sm:block"></div>
                                            <div className="h-6 bg-gray-200 rounded w-1/2"></div>
                                        </div>
                                    </div>
                                ))}
                            </div>
                        </div>
                    ))}
                </div>
                ) : searchQuery.trim() !== '' ? (() => {
                    const searchResults = products.filter(p =>
                    p.name.toLowerCase().includes(searchQuery.toLowerCase()) ||
                    p.description.toLowerCase().includes(searchQuery.toLowerCase())
                    );
                    return (
                    <section>
                        <SectionTitle title={`Resultados para "${searchQuery}"`} />
                        {searchResults.length > 0 ? (
                        <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-4 sm:gap-6">
                            {searchResults.map(product => (
                            <ProductCard key={product.id} product={product} onProductClick={handleProductClick} />
                            ))}
                        </div>
                        ) : (
                        <p className="text-center text-gray-500 mt-8">Nenhum produto encontrado.</p>
                        )}
                    </section>
                    );
                })() : (
                    selectedCategory === 'Todos' ? (
                        categoriesWithProducts.map(category => {
                            const categoryProducts = products.filter(p => p.category === category);
                            if (categoryProducts.length === 0) return null;
                            return (
                                <section key={category}>
                                    <SectionTitle title={category} />
                                    <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-4 sm:gap-6">
                                        {categoryProducts.map(product => (
                                            <ProductCard key={product.id} product={product} onProductClick={handleProductClick} />
                                        ))}
                                    </div>
                                </section>
                            )
                        })
                    ) : (() => {
                        const categoryProducts = products.filter(p => p.category === selectedCategory);
                        return (
                        <section>
                            <SectionTitle title={selectedCategory} />
                            <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-4 sm:gap-6">
                                {categoryProducts.map(product => (
                                <ProductCard
                                    key={product.id}
                                    product={product}
                                    onProductClick={handleProductClick}
                                />
                                ))}
                            </div>
                        </section>
                        );
                    })()
                )}
            </div>
            </main>
            <Footer onNavigate={(target) => {
                if (target === 'login' && isAuthenticated) {
                    setView('admin');
                } else {
                    setView(target);
                }
            }} />
            {cartItems.length > 0 && <div className="h-24 sm:h-28" />}
        </div>
        <StoreInfoModal 
            isOpen={isStoreInfoModalOpen}
            onClose={() => setStoreInfoModalOpen(false)}
            storeInfo={storeInfo}
        />
        <CategoryMenuModal
            isOpen={isCategoryMenuOpen}
            onClose={() => setCategoryMenuOpen(false)}
            categories={categoriesWithProducts}
            onSelectCategory={handleModalCategorySelect}
        />
        <ProductDetailModal 
            product={selectedProduct}
            onClose={handleCloseModal}
            onAddToCart={handleAddToCart}
        />
        <CartButton 
            itemCount={cartItems.reduce((sum, item) => sum + item.quantity, 0)}
            totalPrice={cartItems.reduce((sum, item) => sum + item.price * item.quantity, 0)}
            onClick={handleGoToCheckout}
        />
        <OrderTrackingModal
            isOpen={isOrderTrackingOpen}
            onClose={() => setIsOrderTrackingOpen(false)}
            onTrackOrder={handleTrackOrder}
            initialOrders={activeOrders}
        />
        </>
    );
  }


  switch (view) {
    case 'login':
      return <LoginPage
        onLoginSuccess={() => {
          setView('admin');
        }}
        onNavigateBack={() => setView('menu')}
      />;
    case 'admin':
      if (!isAuthenticated) {
        return <div className="min-h-screen flex items-center justify-center">Verificando acesso...</div>;
      }
      return <AdminPage
        products={products}
        categories={categories}
        storeInfo={storeInfo}
        onAddProduct={handleAddProduct}
        onUpdateProduct={handleUpdateProduct}
        onDeleteProduct={handleDeleteProduct}
        onUpdateStoreInfo={handleUpdateStoreInfo}
        onAddCategory={handleAddCategory}
        onDeleteCategory={handleDeleteCategory}
        onUpdateCategoryOrder={handleUpdateCategoryOrder}
        onToggleCategoriesArchive={handleToggleCategoriesArchive}
        onNavigateBack={() => setView('menu')}
        onLogout={handleLogout}
        onRefreshData={fetchInitialData}
      />;
    case 'checkout':
        return <CheckoutPage 
            cartItems={cartItems}
            storeInfo={storeInfo}
            onNavigateBack={() => {
                setView('menu');
            }}
            onOrderSuccess={handleOrderSuccess}
            onUpdateQuantity={handleUpdateCartQuantity}
            onRemoveItem={handleRemoveFromCart}
        />;
    case 'orderSuccess':
        return <OrderSuccessPage
            order={orderSuccessData}
            storeInfo={storeInfo}
            onNavigateBack={() => setView('menu')}
        />
    default:
      return renderMenu();
  }
};

export default App;
